Lemma art_steps_total : forall work G c, art_rg_ok G -> art_rels_pre G work -> 1 <= c <= 30 ->
  Z.of_nat (length (cl_cache (rg_cls (art_rel_steps work G) c))) + Z.of_nat (length (cl_free (rg_cls (art_rel_steps work G) c)))
